<pre class="lang-cpp prettyprint-override"><code>std::set_terminate([]
{
    std::exception_ptr eptr = std::current_exception();

    if (!eptr)
    {
        std::cerr &lt;&lt; &quot;Terminate called without an active exception.\n&quot;;
        std::abort();
    }

    auto lambda = [](auto &amp;self, std::exception &amp;e) -&gt; void
    {
        try
        {
            std::rethrow_if_nested(e);
        }
        catch (std::exception &amp;sub_e)
        {
            std::cerr &lt;&lt; &quot;* &quot; &lt;&lt; sub_e.what() &lt;&lt; '\n';
            self(self, sub_e);
        }
        catch (...)
        {
            std::cerr &lt;&lt; &quot;Followed by an unknown exception.\n&quot;;
        }
    };

    try
    {
        std::rethrow_exception(eptr);
    }
    catch (std::exception &amp;e)
    {
        std::cerr &lt;&lt; &quot;Terminated with exception:\n&quot;;
        std::cerr &lt;&lt; &quot;* &quot; &lt;&lt; e.what() &lt;&lt; '\n';
        lambda(lambda, e);
    }
    catch (...)
    {
        std::cerr &lt;&lt; &quot;Terminated with unknown exception.\n&quot;;
    }

    std::abort();
});
</code></pre>
<p>I'm using a vintage pre-C++23 recursive lambda for compatibility with older standards. In C++23 and newer, you could do this instead:</p>
<pre class="lang-cpp prettyprint-override"><code>auto lambda = [](this auto &amp;self, std::exception &amp;e) -&gt; void
{
    // ...
    self(sub_e);
};

lambda(e);
</code></pre>
